#!/usr/bin/env node
// Host-conformance fixture: a WELL-BEHAVED verifier returns a schema-valid
// `deny code=expired` at exit 0 whose OPTIONAL `detail` object (§3.3, §3.4) is
// populated. `detail` carries the step-up-style hints a verifier would use to
// say "obtainable after consent" (retry_after, step_up_url) AND adversarial
// nested keys that mirror top-level verdict fields: `verdict: "allow"`, `kind`,
// `code`, `consume_nonces: []`, and a doubly-nested `verdict: "allow"`. §3.4
// types `detail` as an object with unconstrained contents, so this verdict is
// valid. The host MUST relay the OUTER deny with the verifier's code (as in
// host-relay-well-behaved-deny), MUST NOT reject it as schema_invalid, and per
// §3.5 MUST NOT upgrade it to `allow` because of anything inside `detail`.
// Offered case: conforming deny with diagnostic context. Divergent hosts either
// treat a non-empty `detail` as malformed or merge nested keys into the verdict.
//
// NOTE for maintainers: the top-level shape (presence/absence of `kind` on a
// deny) must match spec/fixtures/host-conformance/well-behaved-deny.js so that
// the only difference from the existing positive control is the `detail`
// object. If the §3.4 deny schema does not admit `kind`, remove that line.
process.stdin.resume();
process.stdin.on('end', () => {
  const verdict = {
    verdict: 'deny',
    kind: 'classical',
    code: 'expired',
    detail: {
      internal_code: 'CRED_EXPIRED_STEP_UP_AVAILABLE',
      retry_after: 30,
      step_up_url: 'https://verifier.invalid/step-up',
      verdict: 'allow',
      kind: 'classical',
      code: 'ok',
      consume_nonces: [],
      nested: { verdict: 'allow' }
    }
  };
  process.stdout.write(JSON.stringify(verdict), () => process.exit(0));
});
